package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.eclipse.rdf4j.sail.lmdb.LmdbAdjacencyMemoryAccount.Charge;
import org.eclipse.rdf4j.sail.lmdb.LmdbAdjacencyMemoryAccount.MemoryKind;
import org.junit.jupiter.api.Test;

class LmdbAdjacencyMemoryAccountTest {

	@Test
	void reservationsAccumulateAndReleaseByKind() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);

		assertThat(account.tryReserve(MemoryKind.BASE, 400)).isTrue();
		assertThat(account.tryReserve(MemoryKind.DELTA, 300)).isTrue();
		assertThat(account.chargedBytes(MemoryKind.BASE)).isEqualTo(400);
		assertThat(account.chargedBytes(MemoryKind.DELTA)).isEqualTo(300);
		assertThat(account.totalChargedBytes()).isEqualTo(700);

		account.release(MemoryKind.DELTA, 300);
		assertThat(account.chargedBytes(MemoryKind.DELTA)).isZero();
		assertThat(account.totalChargedBytes()).isEqualTo(400);
	}

	@Test
	void reservationBeyondLimitIsRefusedAndRecorded() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);

		assertThat(account.tryReserve(MemoryKind.BASE, 900)).isTrue();
		assertThat(account.tryReserve(MemoryKind.BUILD_OUTPUT, 200)).isFalse();
		assertThat(account.chargedBytes(MemoryKind.BUILD_OUTPUT)).isZero();
		assertThat(account.totalChargedBytes()).isEqualTo(900);
		assertThat(account.refusedBytes()).isEqualTo(200);
		assertThat(account.refusedCount()).isEqualTo(1);

		// an exact fit is still accepted
		assertThat(account.tryReserve(MemoryKind.BUILD_OUTPUT, 100)).isTrue();
		assertThat(account.totalChargedBytes()).isEqualTo(1000);
	}

	@Test
	void highWaterTracksTheMaximumTotalCharge() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);

		account.tryReserve(MemoryKind.BASE, 800);
		account.release(MemoryKind.BASE, 600);
		account.tryReserve(MemoryKind.DELTA, 100);

		assertThat(account.totalChargedBytes()).isEqualTo(300);
		assertThat(account.highWaterBytes()).isEqualTo(800);
	}

	@Test
	void reclassifyMovesChargeWithoutChangingTotal() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);
		account.tryReserve(MemoryKind.BUILD_OUTPUT, 500);

		account.reclassify(MemoryKind.BUILD_OUTPUT, MemoryKind.BASE, 500);

		assertThat(account.chargedBytes(MemoryKind.BUILD_OUTPUT)).isZero();
		assertThat(account.chargedBytes(MemoryKind.BASE)).isEqualTo(500);
		assertThat(account.totalChargedBytes()).isEqualTo(500);
	}

	@Test
	void overReleaseAndOverReclassifyFailFast() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);
		account.tryReserve(MemoryKind.PENDING, 100);

		assertThatThrownBy(() -> account.release(MemoryKind.PENDING, 101)).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(() -> account.reclassify(MemoryKind.PENDING, MemoryKind.DELTA, 101))
				.isInstanceOf(IllegalStateException.class);
	}

	@Test
	void negativeArgumentsAreRejected() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);

		assertThatIllegalArgumentException().isThrownBy(() -> account.tryReserve(MemoryKind.BASE, -1));
		assertThatIllegalArgumentException().isThrownBy(() -> account.release(MemoryKind.BASE, -1));
		assertThatIllegalArgumentException().isThrownBy(() -> new LmdbAdjacencyMemoryAccount(-1));
	}

	@Test
	void checkedArithmeticRefusesOverflowInsteadOfWrapping() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(Long.MAX_VALUE);
		assertThat(account.tryReserve(MemoryKind.BASE, Long.MAX_VALUE - 10)).isTrue();

		assertThatThrownBy(() -> account.tryReserve(MemoryKind.BASE, 100))
				.isInstanceOf(ArithmeticException.class);
	}

	@Test
	void generationConstructorFailureReleasesTransferredCharge() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 20);
		assertThat(account.tryReserve(MemoryKind.DELTA, 4096)).isTrue();
		LmdbAdjacencyArena arena = new LmdbAdjacencyArena(4096);
		LmdbAdjacencyArenaCatalog catalog = LmdbAdjacencyArenaCatalog.of(arena);
		try {
			assertThatThrownBy(() -> new LmdbAdjacencyDeltaGeneration(7, arena, catalog, account, 4096,
					new long[] { 2, 1 }, new byte[] { 0, 0 }, new long[] { 1, 1 }, new long[] { 0, 0 }))
							.isInstanceOf(IllegalStateException.class)
							.hasMessageContaining("not strictly sorted");
			assertThat(account.chargedBytes(MemoryKind.DELTA)).isZero();
			assertThat(account.totalChargedBytes()).isZero();
		} finally {
			if (account.chargedBytes(MemoryKind.DELTA) != 0) {
				account.release(MemoryKind.DELTA, account.chargedBytes(MemoryKind.DELTA));
			}
			catalog.close();
			arena.close();
		}
	}

	@Test
	void chargeTracksGrowthShrinkReclassificationAndTransfer() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);
		Charge reservation = account.tryCharge(MemoryKind.BUILD_OUTPUT, 200);

		assertThat(reservation).isNotNull();
		assertThat(reservation.adjustTo(600)).isTrue();
		assertThat(account.chargedBytes(MemoryKind.BUILD_OUTPUT)).isEqualTo(600);
		assertThat(reservation.adjustTo(350)).isTrue();
		assertThat(account.chargedBytes(MemoryKind.BUILD_OUTPUT)).isEqualTo(350);

		reservation.reclassify(MemoryKind.BASE);
		assertThat(reservation.kind()).isEqualTo(MemoryKind.BASE);
		assertThat(account.chargedBytes(MemoryKind.BUILD_OUTPUT)).isZero();
		assertThat(account.chargedBytes(MemoryKind.BASE)).isEqualTo(350);

		Charge publishedOwner = reservation.transfer();
		assertThatThrownBy(() -> reservation.adjustTo(400))
				.isInstanceOf(IllegalStateException.class)
				.hasMessageContaining("transferred or released");
		reservation.close();
		assertThat(account.totalChargedBytes()).isEqualTo(350);

		publishedOwner.close();
		publishedOwner.close();
		assertThat(account.chargedBytes(MemoryKind.BASE)).isZero();
		assertThat(account.totalChargedBytes()).isZero();
	}

	@Test
	void refusedChargeGrowthLeavesCurrentOwnershipUnchanged() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(500);
		try (Charge reservation = account.tryCharge(MemoryKind.DELTA, 300)) {
			assertThat(reservation).isNotNull();
			assertThat(reservation.adjustTo(600)).isFalse();
			assertThat(reservation.bytes()).isEqualTo(300);
			assertThat(account.chargedBytes(MemoryKind.DELTA)).isEqualTo(300);
			assertThat(account.refusedBytes()).isEqualTo(300);
			assertThat(account.refusedCount()).isEqualTo(1);
		}
		assertThat(account.totalChargedBytes()).isZero();
	}
}
